<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">MVP · Innovation</p><h1>Innovations</h1><p>Manage prototypes, patents, software, devices, processes, products, and services.</p></div><?php if($canCreate):?><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/innovations/create">Create innovation</a><?php endif;?></section><section class="admin-panel"><h2><?=count($innovations)?> innovation<?=count($innovations)===1?'':'s'?></h2><?php if($innovations===[]):?><p class="admin-empty">No innovations have been added.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Innovation</th><th>Type</th><th>Stage</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($innovations as$item):?><tr><th><?=View::escape($item['name'])?><small><?=View::escape($item['department_name']??'No lead department')?></small></th><td><?=View::escape(ucfirst($item['innovation_type']))?></td><td><?=View::escape(ucfirst($item['development_stage']??'Not set'))?></td><td><?=View::escape($item['status'])?></td><td><div class="table-actions"><?php if($canEdit):?><a href="<?=View::escape($baseUrl)?>admin/innovations/<?=(int)$item['id']?>/edit">Edit</a><?php $action=$item['status']==='published'?'archive':($item['status']==='archived'?'restore':'publish');if($action!=='publish'||$canPublish):?><form method="post" action="<?=View::escape($baseUrl)?>admin/innovations/<?=(int)$item['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$action?>"><?=ucfirst($action)?></button></form><?php endif;endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
